import re
import sys
import argparse
import json

def extract_log_data(log_line):
    """
    Extracts timestamp, status code, and request ID from an Nginx access log line.

    Format: $remote_addr - $remote_user [$time_local] "$request" $status $body_bytes_sent "$http_referer" "$http_user_agent" "$request_id"
    """
    # Regex designed for Nginx access logs with a custom request_id field
    # We use non-greedy matching for the request part to avoid issues with escaped quotes
    regex = r'^[^ ]+ - [^ ]+ \[(?P<timestamp>\d{2}/(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)/\d{4}:\d{2}:\d{2}:\d{2} [+-]\d{4})\] ".*?" (?P<status>[1-5]\d{2}) \d+ ".*?" ".*?" "(?P<request_id>[^"]*)"'

    match = re.match(regex, log_line)
    if match:
        return match.groupdict()
    return None

def process_logs(input_stream, output_format='tsv'):
    """Processes log lines from the input stream and prints them in the specified format."""
    for line in input_stream:
        line = line.strip()
        if not line:
            continue
        data = extract_log_data(line)
        if data:
            if output_format == 'json':
                print(json.dumps(data))
            else:
                # Default to TSV: timestamp, status, request_id
                print(f"{data['timestamp']}\t{data['status']}\t{data['request_id']}")

def test():
    test_cases = [
        {
            "name": "Standard Valid Line",
            "line": '127.0.0.1 - - [21/May/2026:10:00:00 +0000] "GET / HTTP/1.1" 200 123 "-" "-" "req-123"',
            "expected": {"timestamp": "21/May/2026:10:00:00 +0000", "status": "200", "request_id": "req-123"}
        },
        {
            "name": "Different Status Code (404)",
            "line": '192.168.1.1 - user1 [21/May/2026:10:05:00 +0000] "POST /api/v1/data HTTP/1.1" 404 567 "https://referer.com" "Mozilla/5.0" "a1b2c3d4"',
            "expected": {"timestamp": "21/May/2026:10:05:00 +0000", "status": "404", "request_id": "a1b2c3d4"}
        },
        {
            "name": "Empty Request ID",
            "line": '10.0.0.1 - - [21/May/2026:10:10:00 +0000] "HEAD /status HTTP/1.1" 500 0 "-" "-" ""',
            "expected": {"timestamp": "21/May/2026:10:10:00 +0000", "status": "500", "request_id": ""}
        },
        {
            "name": "Malformed Timestamp (Invalid Month)",
            "line": '127.0.0.1 - - [21/BadMonth/2026:10:00:00 +0000] "GET / HTTP/1.1" 200 123 "-" "-" "req-123"',
            "expected": None
        },
        {
            "name": "Malformed Status Code (Not 3 digits)",
            "line": '127.0.0.1 - - [21/May/2026:10:00:00 +0000] "GET / HTTP/1.1" 20 123 "-" "-" "req-123"',
            "expected": None
        },
        {
            "name": "Missing Final Quoted Field",
            "line": '127.0.0.1 - - [21/May/2026:10:00:00 +0000] "GET / HTTP/1.1" 200 123 "-" "-"',
            "expected": None
        },
        {
            "name": "Escaped Quotes in Request",
            "line": '127.0.0.1 - - [21/May/2026:10:00:00 +0000] "GET /path?q=\"test\" HTTP/1.1" 200 123 "-" "-" "req-123"',
            "expected": {"timestamp": "21/May/2026:10:00:00 +0000", "status": "200", "request_id": "req-123"}
        }
    ]

    passed_count = 0
    for case in test_cases:
        result = extract_log_data(case["line"])
        if result == case["expected"]:
            print(f"[PASS] {case['name']}")
            passed_count += 1
        else:
            print(f"[FAIL] {case['name']}")
            print(f"  Expected: {case['expected']}")
            print(f"  Actual:   {result}")

    print(f"\nTests passed: {passed_count}/{len(test_cases)}")
    return passed_count == len(test_cases)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Extract data from Nginx logs.")
    parser.add_argument("files", nargs="*", help="Files to process (reads from stdin if omitted)")
    parser.add_argument("--format", choices=["tsv", "json"], default="tsv", help="Output format (default: tsv)")
    parser.add_argument("--test", action="store_true", help="Run internal tests and exit")

    args = parser.parse_args()

    if args.test:
        success = test()
        sys.exit(0 if success else 1)

    if not args.files:
        process_logs(sys.stdin, args.format)
    else:
        for file_path in args.files:
            try:
                with open(file_path, 'r') as f:
                    process_logs(f, args.format)
            except FileNotFoundError:
                print(f"Error: File not found: {file_path}", file=sys.stderr)
                sys.exit(1)
            except Exception as e:
                print(f"Error processing {file_path}: {e}", file=sys.stderr)
                sys.exit(1)
